import random
from collections import defaultdict, deque

# Define color classes for 3-coloring: sizes 6,6,7
parts = [list(range(0,6)), list(range(6,12)), list(range(12,19))]
color = {}
for i, p in enumerate(parts):
    for v in p:
        color[v] = i

# All possible edges between different colors
possible_edges = []
for i in range(19):
    for j in range(i+1,19):
        if color[i] != color[j]:
            possible_edges.append((i,j))

print(len(possible_edges)) # should be 120

def has_short_path(adj, u, v, max_len=5):
    # BFS from u to find if dist to v <= max_len
    if u == v: return True
    visited = [False] * 19
    dist = [-1] * 19
    q = deque([u])
    visited[u] = True
    dist[u] = 0
    while q:
        x = q.popleft()
        if dist[x] >= max_len:
            continue
        for y in adj[x]:
            if not visited[y]:
                visited[y] = True
                dist[y] = dist[x] + 1
                if y == v:
                    return True
                q.append(y)
    return False

# Greedy random add
random.seed(42)  # for reproducibility
random.shuffle(possible_edges)
adj = defaultdict(list)
edges = []
for e in possible_edges:
    u, v = e
    if not has_short_path(adj, u, v, 5):
        adj[u].append(v)
        adj[v].append(u)
        edges.append(e)
    if len(edges) >= 32:
